import{z as d,x as B,o as n,c as p,q as s,j as o,D as i,d as l,s as t,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"内联启发","description":"","frontmatter":{"title":"内联启发","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/inlining-heuristics.md","filePath":"cs/inlining-heuristics.md","lastUpdated":1791063341000}'),c={name:"cs/inlining-heuristics.md"};function A(h,a,m,u,D,C){const r=B("Mermaid");return n(),p("div",null,[a[2]||(a[2]=s('<h1 id="内联启发" tabindex="-1">内联启发 <a class="header-anchor" href="#内联启发" aria-label="Permalink to &quot;内联启发&quot;">​</a></h1><div class="epigraph"><p>内联用调用点的体替换 `call`，消除开销并暴露过程内优化。预算、热度与是否递归决定做不做，而不是「凡是能内联都做」。</p><footer>—— 据 Davidson and Holler；Ayres 等内联研究；Appel；龙书过程间优化整理</footer></div><p>上一课<a href="/cs/interprocedural-callgraph">调用图</a>知道 callee。缺口是<strong>复制体的决策</strong>：小函数几乎总内联；大函数只在热路径；递归要阈值。本课钉启发与副作用（代码膨胀、编译时间），不写尾调用——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每次调用有 ABI 开销与屏障（许多优化不跨 <code>call</code>）。内联后常量实参触发 SCCP，虚调用可能去虚。代价：I-cache、编译时间、调试。缺口是<strong>成本模型</strong>，不是 CG 构造。</p><p><span class="marginnote">数字实例：一个 2 KB 的热函数被内联进 10 个调用点，指令体积大约多出 18 KB——这还只是一层。代码膨胀的真实代价在 I-cache：热循环的工作集被撑大后，取指miss变多，「消除了 call 开销」省下的几拍可能远不够赔。</span></p><p>始终内联：<code>always_inline</code>、模板单态化后的小函数。永不：函数指针外部、<code>noinline</code>、过大。</p><h3 id="内联不是宏" tabindex="-1">内联不是宏 <a class="header-anchor" href="#内联不是宏" aria-label="Permalink to &quot;内联不是宏&quot;">​</a></h3><p>宏是记号改写，无作用域；内联是 IR 级，遵守作用域与类型。C 的 <code>inline</code> 关键字还与链接（弱符号）纠缠，后课符号。</p><p><span class="marginnote">经典编译器内联启发式。LLVM InlineCost。PGO 后课提供热度。本课静态：体大小、调用深度、是否有 alloca。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自底向上沿 CG（先叶）。对每个调用点打分：指令数、是否可常量传播、是否在循环。超过预算停。递归：允许浅层或只内联一次（peel）。</p>',12)),(n(),o(E,null,{default:i(()=>[t(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CG%5B%22%E8%B0%83%E7%94%A8%E5%9B%BE%22%5D%20--%3E%20COST%5B%22%E4%BB%A3%E4%BB%B7%20%2F%20%E6%94%B6%E7%9B%8A%22%5D%0A%20%20COST%20--%3E%20IN%5B%22%E5%A4%8D%E5%88%B6%E4%BD%93%22%5D%0A%20%20IN%20--%3E%20OPT%5B%22SCCP%20%2F%20DCE%20%2F%20LICM%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与单态化：特化后的体更小更值得内联。与栈：内联加深帧，除非再缩。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[l("间接调用：先去虚（唯一目标）再内联。失败则留 "),e("code",null,"call"),l("。不要内联改变可观察异常表顺序的语言细节而不更新表。")],-1)),a[6]||(a[6]=e("p",null,"常量实参在内联后引发的连锁优化：",-1)),(n(),o(E,null,{default:i(()=>[t(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%B0%83%E7%94%A8%E7%82%B9%EF%BC%9Af(4096)%22%5D%20--%3E%20B%5B%22%E5%A4%8D%E5%88%B6%20callee%20%E4%BD%93%E5%88%B0%E8%B0%83%E7%94%A8%E7%82%B9%22%5D%0A%20%20B%20--%3E%20C%5B%22SCCP%20%E8%AE%A9%204096%20%E6%B2%BF%E4%BD%93%E4%BC%A0%E6%92%AD%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BE%9D%E8%B5%96%E8%AF%A5%E5%B8%B8%E9%87%8F%E7%9A%84%E6%AD%BB%E5%88%86%E6%94%AF%E8%A2%AB%E5%89%AA%E6%8E%89%22%5D%0A%20%20D%20--%3E%20E%5B%22DCE%20%2F%20LICM%20%E7%BB%A7%E7%BB%AD%E6%B8%85%E7%90%86%E6%AE%8B%E7%95%99%22%5D%0A%20%20E%20--%3E%20F%5B%22%E7%89%B9%E5%8C%96%E5%90%8E%E7%9A%84%E4%BD%93%E5%8F%AF%E8%83%BD%E6%AF%94%E5%8E%9F%E8%B0%83%E7%94%A8%E6%9B%B4%E5%B0%8F%E6%9B%B4%E5%BF%AB%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">术语翻译：「去虚化」就是编译器发现某个虚调用实际上只有一个可能目标，把它改写成直接调用——改完才有资格内联。去虚与内联互为放大器：内联暴露信息让去虚更容易，去虚产生的小直接调用又更值得内联。</span></p><p><span class="marginnote">常见误区：初学者容易以为「能内联就内联，反正更快」。预算存在的理由正是反例：大函数反复复制推高 I-cache 压力与编译时间，冷路径上的内联几乎零收益。启发式做的是打分排序，不是无条件复制。</span></p><p>链接期内联（LTO）看见其它 TU 的体——后课 LTO。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写完整 profile 计数。后课默认：内联由预算与热度约束。下一课尾调用：不内联也能把调用变成跳转。</p><p>也不把内联当混淆（故意复制）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内联消除调用并暴露优化；膨胀是代价。</li><li>启发：大小、热度、递归深度。</li><li>与摘要分析互补：不内联也能传 mod/ref。</li><li>出处：Davidson/Holler；Appel；龙书；对照 LLVM InlineCost。</li></ul>',8))])}const T=d(c,[["render",A]]);export{_ as __pageData,T as default};
